def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the uniform separator, which may be vertical or horizontal.
    sep_col = next((c for c in range(w)
                    if len({grid[r][c] for r in range(h)}) == 1), None)
    sep_row = next((r for r in range(h)
                    if len(set(grid[r])) == 1), None)

    if sep_col is not None:
        panel = [row[:sep_col] for row in grid]
        sep_color = grid[0][sep_col]
    else:
        panel = grid[:sep_row]
        sep_color = grid[sep_row][0]

    colors = [v for row in panel for v in row]
    bg = max(set(colors), key=colors.count)
    fg = next((v for v in colors if v != bg), bg)

    return [[3 if v == fg else fg for v in row] for row in panel]
